import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import type { AppState, Category, Task } from '../types';
import {
  closeDay,
  completeTask,
  dismissPunishment,
  ensureDailyPlan,
  processDayRollover,
  purchaseReward,
  uncompleteTask,
} from '../lib/gameLogic';
import { loadState, resetState, saveState } from '../lib/storage';

interface AppStoreValue {
  state: AppState;
  refresh: () => void;
  completeTask: (taskId: string) => void;
  uncompleteTask: (taskId: string) => void;
  closeDay: () => void;
  purchaseReward: (rewardId: string) => void;
  dismissPunishment: (id: string) => void;
  updateSettings: (partial: Partial<AppState['settings']>) => void;
  updateCategory: (category: Category) => void;
  addCategory: (category: Category) => void;
  updateTask: (task: Task) => void;
  addTask: (task: Task) => void;
  resetAll: () => void;
}

const AppStoreContext = createContext<AppStoreValue | null>(null);

export function AppStoreProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>(() => {
    let s = loadState();
    s = processDayRollover(s);
    s = ensureDailyPlan(s);
    saveState(s);
    return s;
  });

  const persist = useCallback((next: AppState) => {
    setState(next);
    saveState(next);
  }, []);

  useEffect(() => {
    let s = processDayRollover(state);
    s = ensureDailyPlan(s);
    if (s !== state) persist(s);
  }, []);

  const refresh = useCallback(() => {
    let s = loadState();
    s = processDayRollover(s);
    s = ensureDailyPlan(s);
    persist(s);
  }, [persist]);

  const value = useMemo<AppStoreValue>(
    () => ({
      state,
      refresh,
      completeTask: (taskId) => persist(completeTask(state, taskId)),
      uncompleteTask: (taskId) => persist(uncompleteTask(state, taskId)),
      closeDay: () => persist(closeDay(state)),
      purchaseReward: (rewardId) => persist(purchaseReward(state, rewardId)),
      dismissPunishment: (id) => persist(dismissPunishment(state, id)),
      updateSettings: (partial) =>
        persist({ ...state, settings: { ...state.settings, ...partial } }),
      updateCategory: (category) =>
        persist({
          ...state,
          categories: state.categories.map((c) =>
            c.id === category.id ? category : c,
          ),
        }),
      addCategory: (category) =>
        persist({ ...state, categories: [...state.categories, category] }),
      updateTask: (task) =>
        persist({
          ...state,
          tasks: state.tasks.map((t) => (t.id === task.id ? task : t)),
        }),
      addTask: (task) => persist({ ...state, tasks: [...state.tasks, task] }),
      resetAll: () => persist(resetState()),
    }),
    [state, persist, refresh],
  );

  return (
    <AppStoreContext.Provider value={value}>{children}</AppStoreContext.Provider>
  );
}

export function useAppStore(): AppStoreValue {
  const ctx = useContext(AppStoreContext);
  if (!ctx) throw new Error('useAppStore must be used within AppStoreProvider');
  return ctx;
}

import { NavLink, Outlet } from 'react-router-dom';

const navItems = [
  { to: '/', label: 'Accueil', icon: '🏠' },
  { to: '/today', label: "Aujourd'hui", icon: '☀️' },
  { to: '/library', label: 'Bibliothèque', icon: '📚' },
  { to: '/rewards', label: 'Récompenses', icon: '🏆' },
  { to: '/punishments', label: 'Punitions', icon: '⚡' },
  { to: '/settings', label: 'Paramètres', icon: '⚙️' },
];

export function Layout() {
  return (
    <motion className="app-shell">
      <header className="app-header">
        <h1 className="app-title">Sissy Training</h1>
        <p className="app-tagline">Discipline & progression</p>
      </header>
      <main className="app-main">
        <Outlet />
      </main>
      <nav className="bottom-nav" aria-label="Navigation principale">
        {navItems.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            end={item.to === '/'}
            className={({ isActive }) =>
              `nav-link${isActive ? ' nav-link--active' : ''}`
            }
          >
            <span className="nav-icon" aria-hidden>
              {item.icon}
            </span>
            <span className="nav-label">{item.label}</span>
          </NavLink>
        ))}
      </nav>
    </motion>
  );
}

import { xpProgressInLevel } from '../lib/levels';
import type { Level } from '../types';

interface XpBarProps {
  totalXp: number;
  levels: Level[];
  levelName: string;
}

export function XpBar({ totalXp, levels, levelName }: XpBarProps) {
  const { current, max, percent } = xpProgressInLevel(totalXp, levels);

