import { Layout } from './components/Layout';
import { AppStoreProvider } from './hooks/useAppStore';
import { Dashboard } from './pages/Dashboard';
import { Library } from './pages/Library';
import { Punishments } from './pages/Punishments';
import { Rewards } from './pages/Rewards';
import { Settings } from './pages/Settings';
import { Today } from './pages/Today';

export default function App() {
  return (
    <AppStoreProvider>
      <BrowserRouter>
        <Routes>
          <Route element={<Layout />}>
            <Route index element={<Dashboard />} />
            <Route path="today" element={<Today />} />
            <Route path="library" element={<Library />} />
            <Route path="rewards" element={<Rewards />} />
            <Route path="punishments" element={<Punishments />} />
            <Route path="settings" element={<Settings />} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Route>
        </Routes>
      </BrowserRouter>
    </AppStoreProvider>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './index.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

:root {
  --bg: #0d0812;
  --bg-card: #1a1024;
  --bg-elevated: #241533;
  --text: #f3e8ff;
  --text-muted: #a78bb8;
  --accent: #e879f9;
  --accent-2: #c084fc;
  --success: #4ade80;
  --warn: #fb923c;
  --danger: #f87171;
  --radius: 14px;
  --nav-h: 64px;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100dvh;
  background: radial-gradient(ellipse at top, #2a1538 0%, var(--bg) 55%);
}

#root {
  min-height: 100dvh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

button,
input,
select {
  font: inherit;
}

.app-shell {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  max-width: 480px;
  margin: 0 auto;
}

.app-header {
  padding: 1rem 1.25rem 0.5rem;
  text-align: center;
}

.app-title {
  margin: 0;
  font-size: 1.35rem;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.app-tagline {
  margin: 0.15rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.app-main {
  flex: 1;
  padding: 0 1rem calc(var(--nav-h) + var(--safe-bottom) + 1rem);
  overflow-y: auto;
}

.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 480px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
  padding: 0.35rem 0.5rem calc(0.35rem + var(--safe-bottom));
  background: rgba(13, 8, 18, 0.92);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(232, 121, 249, 0.15);
  z-index: 100;
}

@media (min-width: 400px) {
  .bottom-nav {
    grid-template-columns: repeat(6, 1fr);
  }
}

.nav-link {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 0.35rem 0.15rem;
  border-radius: 10px;
  color: var(--text-muted);
  font-size: 0.62rem;
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
}

.nav-link--active {
  color: var(--accent);
  background: rgba(232, 121, 249, 0.12);
}

.nav-icon {
  font-size: 1.1rem;
}

.page {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.page-header h2 {
  margin: 0;
  font-size: 1.25rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid rgba(192, 132, 252, 0.12);
  border-radius: var(--radius);
  padding: 1rem;
}

.card--hero {
  background: linear-gradient(145deg, #2a1538, var(--bg-card));
}

.card--warn {
  border-color: rgba(251, 146, 60, 0.4);
  background: rgba(251, 146, 60, 0.08);
}

.card--success {
  border-color: rgba(74, 222, 128, 0.35);
}

.section-title {
  margin: 0 0 0.75rem;
  font-size: 0.95rem;
  color: var(--accent-2);
}

.muted {
  color: var(--text-muted);
  font-size: 0.85rem;
  margin: 0.25rem 0 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.65rem;
}

.stat-card {
  background: var(--bg-card);
  border: 1px solid rgba(192, 132, 252, 0.15);
  border-radius: var(--radius);
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.stat-card__label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stat-card__value {
  font-size: 1.35rem;
  font-weight: 700;
}

.stat-card__hint {
  font-size: 0.7rem;
  color: var(--text-muted);
}

.xp-bar__header {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  margin-bottom: 0.5rem;
}

.xp-bar__level {
  font-weight: 600;
}

.xp-bar__xp {
  color: var(--text-muted);
}

.xp-bar__track {
  height: 10px;
  background: rgba(0, 0, 0, 0.35);
  border-radius: 999px;
  overflow: hidden;
}

.xp-bar__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-2), var(--accent));
  border-radius: 999px;
  transition: width 0.35s ease;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.65rem 1rem;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.15s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn--primary {
  background: linear-gradient(135deg, var(--accent-2), var(--accent));
  color: #1a0a22;
}

.btn--ghost {
  background: transparent;
  border: 1px solid rgba(232, 121, 249, 0.35);
  color: var(--text);
}

.btn--danger {
  background: rgba(248, 113, 113, 0.15);
  color: var(--danger);
  border: 1px solid rgba(248, 113, 113, 0.35);
  margin-top: 1rem;
  width: 100%;
}

.btn--small {
  padding: 0.4rem 0.65rem;
  font-size: 0.8rem;
}

.btn--block {
  width: 100%;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.task-card {
  background: var(--bg-elevated);
  border-radius: var(--radius);
  border: 1px solid rgba(192, 132, 252, 0.1);
  transition: border-color 0.2s, opacity 0.2s;
}

.task-card--done {
  opacity: 0.72;
  border-color: rgba(74, 222, 128, 0.35);
}

.task-card--disabled {
  opacity: 0.5;
}

.task-card__label {
  display: flex;
  gap: 0.75rem;
  padding: 0.85rem;
  cursor: pointer;
}

.task-card__check {
  width: 1.2rem;
  height: 1.2rem;
  margin-top: 0.2rem;
  accent-color: var(--accent);
}

.task-card__body {
  flex: 1;
  min-width: 0;
}

.task-card__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}

.task-card__badge {
  font-size: 0.7rem;
  padding: 0.15rem 0.45rem;
  border: 1px solid;
  border-radius: 999px;
}

.task-card__freq {
  font-size: 0.65rem;
  color: var(--text-muted);
}

.task-card__title {
  margin: 0;
  font-size: 0.95rem;
}

.task-card__desc {
  margin: 0.25rem 0 0;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.task-card__meta {
  display: flex;
  gap: 0.75rem;
  margin-top: 0.5rem;
  font-size: 0.72rem;
  color: var(--text-muted);
}

.task-card__xp {
  color: var(--accent);
  font-weight: 600;
}

.progress-summary {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.progress-ring {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: conic-gradient(
    var(--accent) calc(var(--p) * 1%),
    rgba(255, 255, 255, 0.08) 0
  );
  position: relative;
}

.progress-ring::after {
  content: '';
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  background: var(--bg-card);
}

.progress-ring__value {
  position: relative;
  z-index: 1;
  font-weight: 700;
  font-size: 0.9rem;
}

.filters {
  display: flex;
  gap: 0.5rem;
}

.filters select {
  flex: 1;
  padding: 0.5rem;
  border-radius: 8px;
  border: 1px solid rgba(192, 132, 252, 0.25);
  background: var(--bg-card);
  color: var(--text);
}

.library-section {
  margin-top: 0.5rem;
}

.library-level {
  font-size: 0.85rem;
  color: var(--accent-2);
  margin: 0 0 0.5rem;
}

.locked-hint {
  font-size: 0.75rem;
  color: var(--warn);
  margin: -0.35rem 0 0.5rem 0.85rem;
}

.reward-list,
.punishment-list,
.badge-list,
.history-list,
.edit-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.reward-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.reward-item:last-child {
  border-bottom: none;
}

.reward-item--earned {
  opacity: 1;
}

.reward-item__body {
  flex: 1;
}

.reward-icon {
  font-size: 1.5rem;
}

.cost {
  display: inline-block;
  margin-top: 0.35rem;
  font-size: 0.8rem;
  color: var(--accent);
}

.tag {
  font-size: 0.7rem;
  padding: 0.2rem 0.5rem;
  border-radius: 6px;
}

.tag--ok {
  background: rgba(74, 222, 128, 0.15);
  color: var(--success);
}

.punishment-item h3 {
  margin: 0 0 0.35rem;
}

.punishment-points {
  color: var(--danger);
  font-weight: 600;
}

.history-list li {
  display: flex;
  justify-content: space-between;
  padding: 0.4rem 0;
  font-size: 0.85rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.notice {
  text-align: center;
  padding: 0.75rem;
  border-radius: var(--radius);
  background: rgba(192, 132, 252, 0.1);
  font-size: 0.9rem;
}

.tabs {
  display: flex;
  gap: 0.35rem;
}

.tab {
  flex: 1;
  padding: 0.5rem;
  border: 1px solid rgba(192, 132, 252, 0.2);
  background: var(--bg-card);
  color: var(--text-muted);
  border-radius: 8px;
  cursor: pointer;
}

.tab--active {
  color: var(--accent);
  border-color: var(--accent);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1rem;
}

.field input {
  padding: 0.55rem;
  border-radius: 8px;
  border: 1px solid rgba(192, 132, 252, 0.25);
  background: var(--bg);
  color: var(--text);
}

.form-grid {
  display: grid;
  gap: 0.5rem;
  margin: 0.75rem 0;
}

.form-grid input,
.form-grid select {
  padding: 0.5rem;
  border-radius: 8px;
  border: 1px solid rgba(192, 132, 252, 0.25);
  background: var(--bg);
  color: var(--text);
}

.edit-list__btn {
  width: 100%;
  text-align: left;
  padding: 0.5rem;
  margin-bottom: 0.35rem;
  background: var(--bg);
  border: 1px solid rgba(192, 132, 252, 0.15);
  border-radius: 8px;
  color: var(--text);
  cursor: pointer;
}

