import type { AppState, Category, Task } from '../types';

export function getCategory(
  state: AppState,
  categoryId: string,
): Category | undefined {
  return state.categories.find((c) => c.id === categoryId);
}

export function getTask(state: AppState, taskId: string): Task | undefined {
  return state.tasks.find((t) => t.id === taskId);
}
